def tropical_transport(bijection, energy):
    f_inv = {v: k for k, v in bijection.items()}
    return {x: energy[f_inv[x]] for x in energy}

import math
def landauer_cost(n_bits, kB=1.380649e-23, T=300.0):
    return kB * T * n_bits * math.log(2)

def reversible_extend(states, step):
    def enc(x): return (x, step[x])
    def proj(pair): return pair[1]
    def R(pair): return pair  # identity
    return enc, proj, R

