TROPICAL_SHORTEST_PATH(cost, n):
  dist ← copy(cost)
  for k in 0..n-1:
    for i in 0..n-1:
      for j in 0..n-1:
        dist[i][j] ← min(dist[i][j], dist[i][k] + dist[k][j])
  return dist

